import type { CoreSystemsFixture } from '../enrichment/core-systems.js';
import { confusableVariants } from '../enrichment/match.js';

/**
 * A focused test of customer matching under OCR damage, generated by code so the ground truth is
 * exact. Policy numbers are issued in sequence, so every policy gets a neighbour one OCR confusion
 * away that belongs to somebody else: the realistic worst case for a number without a check digit.
 */
export interface IdentityCase {
  readonly id: string;
  readonly kind: IdentityCaseKind;
  readonly text: string;
  /** Who the letter is really about. */
  readonly truth: string;
}

export type IdentityCaseKind =
  | 'clean number and name'
  | 'clean number, no name'
  | 'OCR slip onto a neighbour, name present'
  | 'OCR slip onto a neighbour, no name'
  | 'letter read in place of a digit, name present';

const NEIGHBOUR_NAMES = [
  'Tomasz Wróblewski',
  'Barbara Dudek',
  'Rafał Pawlak',
  'Elżbieta Sikora',
  'Grzegorz Baran',
  'Monika Szczepańska',
  'Łukasz Michalski',
  'Iwona Krawczyk',
  'Dariusz Adamczyk',
  'Renata Kaczmarek',
  'Paweł Zając',
  'Beata Wróbel',
  'Krzysztof Jabłoński',
  'Halina Król',
];

const letter = (number: string, name?: string): string =>
  `Szanowni Państwo,\nniniejszym wypowiadam umowę ubezpieczenia nr ${number} z zachowaniem okresu wypowiedzenia. Proszę o pisemne potwierdzenie.\n${name ? `Z poważaniem\n${name}` : 'Z poważaniem'}`;

/** Replaces one digit of the serial part with a letter OCR often returns for it. */
function withLookalike(number: string): string {
  const swaps: Readonly<Record<string, string>> = {
    '0': 'O',
    '1': 'l',
    '5': 'S',
    '8': 'B',
    '2': 'Z',
  };
  const cut = number.lastIndexOf('/') + 1;
  for (let i = number.length - 1; i >= cut; i--) {
    const ch = number[i] ?? '';
    const alt = swaps[ch];
    if (alt) return `${number.slice(0, i)}${alt}${number.slice(i + 1)}`;
  }
  return number;
}

export function buildIdentitySuite(base: CoreSystemsFixture): {
  fixture: CoreSystemsFixture;
  cases: IdentityCase[];
} {
  const taken = new Set(base.customers.flatMap((c) => c.policies.map((p) => p.number)));
  const neighbours: CoreSystemsFixture['customers'] = [];
  const cases: IdentityCase[] = [];

  base.customers.forEach((customer, i) => {
    const policy = customer.policies[0]?.number;
    if (!policy) return;
    const slip = confusableVariants(policy).find((v) => !taken.has(v));
    if (!slip) return;
    taken.add(slip);
    neighbours.push({
      id: `N${String(i + 1).padStart(4, '0')}`,
      // Never the customer's own name: namesakes are a separate case, handled by the resolver.
      name:
        NEIGHBOUR_NAMES.filter((n) => n !== customer.name)[i % (NEIGHBOUR_NAMES.length - 1)] ??
        'Jan Nowak',
      ibans: [],
      policies: [{ number: slip, product: 'MOTOR', status: 'ACTIVE' }],
      flags: [],
    });
    const add = (kind: IdentityCaseKind, text: string): void => {
      cases.push({ id: `${customer.id}:${kind}`, kind, text, truth: customer.id });
    };
    add('clean number and name', letter(policy, customer.name));
    add('clean number, no name', letter(policy));
    add('OCR slip onto a neighbour, name present', letter(slip, customer.name));
    add('OCR slip onto a neighbour, no name', letter(slip));
    add(
      'letter read in place of a digit, name present',
      letter(withLookalike(policy), customer.name),
    );
  });

  return { fixture: { ...base, customers: [...base.customers, ...neighbours] }, cases };
}
